"""Build the PCB1 teaching deck from the same exercises and frozen records."""
from pathlib import Path
import html
import json
import os
import shutil

ROOT=Path(__file__).resolve().parents[1]
KIT=ROOT.parents[1]
BASE='/' + os.environ.get('DECK_BASE','').strip('/') + '/'
if BASE=='//': BASE='/'
DATA=KIT/'data/inspection-v1'
if DATA.exists():
    records=json.loads((DATA/'records.json').read_text(encoding='utf-8'))
    for label, name in [(0,'normal'),(1,'defect')]:
        row=next(r for r in records if r['partition']=='fit' and r['label']==label)
        shutil.copy2(DATA/row['image'],ROOT/'public/images'/f'fit-{name}.jpg')
RETEST=KIT/'evidence/inspection-teaching-retest-v2/results.json'
if RETEST.exists():shutil.copy2(RETEST,ROOT/'public/recorded-retest.json')
recorded=json.loads((ROOT/'public/recorded-retest.json').read_text(encoding='utf-8'))
slides=[]

def eval_capture(detail=False, items=()):
    source_path=ROOT/'data/evaltables-native.json'
    source=json.loads(source_path.read_text(encoding='utf-8')) if source_path.exists() else {}
    image='evaltables-native-mask.png' if detail == 'mask' else 'evaltables-native-detail.png' if detail else 'evaltables-native.png'
    url=source.get('detail_url' if detail else 'url',source.get('url',''))
    rendered='<img src="/images/'+image+'" alt="Native Forge Evaluation Tables Preview showing saved workshop results">'
    if url: rendered='<a href="'+url+'">'+rendered+'</a>'
    positions=[(28.3,40),(28.3,22),(28.3,88)] if detail == 'mask' else [(28.3,25),(28.3,85.5),(28.3,95)] if detail else [(6,39),(6,79),(6,60)]
    rendered+=''.join('<span class="eval-native-pin" style="left:'+str(x)+'%;top:'+str(y)+'%" aria-hidden="true">'+str(i)+'</span>' for i,(x,y) in enumerate(positions,1))
    notes=''.join('<p><b>'+str(i)+' · '+title+'</b><br>'+text+'</p>' for i,(title,text) in enumerate(items,1))
    caption=source.get('mask_description','Reference defect mask; white marks supplied annotations.') if detail == 'mask' else 'Recorded results in Forge · Evaluation Tables (Preview)'
    return '<div class="eval-native"><div class="eval-native-image">'+rendered+'</div><div class="eval-native-notes">'+notes+'</div></div><p class="eval-native-caption">'+caption+' · '+('<a href="'+url+'">Open this comparison ↗</a>' if url else 'Source link in the capture receipt')+'</p>'


def add(key,title,body,notes,time='',kind='',answer=None):slides.append(dict(key=key,title=title,body=body,notes=notes,time=time,kind=kind,answer=answer))
def code(body,highlight=''):
    return '```python'+(' {'+highlight+'}' if highlight else '')+'\n'+body+'\n```\n'
def note(text):return '<div class="bottom-note">'+text+'</div>'
def pic(name,caption):return f'<div class="figure"><img src="/images/{name}" alt="{html.escape(caption)}"><div class="caption">{caption}</div></div>'
def exercise(key,title,task,steps,check,notes,time,answer=None):
    add(key,title,'<div class="task">'+task+'</div><ol class="exercise-controls">'+''.join('<li>'+s+'</li>' for s in steps)+'</ol><div class="done">Check: '+check+'</div>',notes,time,'exercise',answer)

add('opening','Find defective parts<br>before they ship','<div class="sub">Use real circuit-board photos to compare detectors, review their mistakes, and save a version another engineer can reproduce.</div>'+note('Three hours · CPU classifiers · your own Forge project'), 'The inspection team is fictional. The VisA PCB1 images, masks and recorded comparisons are real. Do not promise that every participant run improves.', '0:00','cover')
add('assignment','The factory has two ways to waste a good morning','<div class="two-col"><div class="box"><h2>A defect gets through</h2><p>A board with a missing or damaged component passes inspection.</p></div><div class="box"><h2>A good board gets held</h2><p>An inspector spends time checking a normal board that the detector rejected.</p></div></div>'+note('Management has requested fewer of both. It has not supplied a third category called “probably fine.”'), 'Ask participants which cost matters in their own work. We will count both errors. The joke does not define the release threshold.', '0:02')
add('real-data','Start with the boards, not the score','<div class="photo-pair"><div><img src="/images/fit-normal.jpg" alt="VisA PCB1 fitting photograph A, viewed from above"><p>Training example A</p></div><div><img src="/images/fit-defect.jpg" alt="VisA PCB1 fitting photograph B, viewed from above"><p>Training example B</p></div></div>'+note('VisA PCB1 · real photographs · labels hidden for this first inspection'), 'Ask learners to identify a region they would inspect. Do not infer a defect type without checking the supplied mask. They will reveal masks in the notebook.', '0:04')
add('dataset','What is in the teaching set?','<div class="cards"><div class="card"><strong>1,104 photographs</strong><p>One PCB family. 1,004 normal boards and 100 defective boards.</p></div><div class="card"><strong>Image labels</strong><p>A board-level normal or defective label is the classifier target.</p></div><div class="card"><strong>Defect masks</strong><p>Annotations let us inspect mistakes. They never enter the classifier.</p></div></div>'+note('VisA, Zou et al. · CC BY 4.0 · the provided supervised split is preserved'), 'Explain the distinction between detecting a defective board and locating its defect. This classifier does the former. A patch-distance heatmap is not a segmentation model.', '0:07')
add('partitions','Separate the data before choosing a model','<div class="flow"><div class="box">397<br><small>fit models</small></div><span>+</span><div class="box">133<br><small>review pool</small></div><span>+</span><div class="box">132<br><small>validation</small></div><span>│</span><div class="box">442<br><small>final test</small></div></div>'+note('Only the authors’ training partition is subdivided. The official test partition stays unchanged.'), 'The 132 validation boards contain 12 defects. A threshold targeting 90 percent recall must catch at least 11. Test data is public for reproduction, so this is a teaching boundary rather than a security barrier.', '0:09')
exercise('connect','Connect to your own experiment','Open the Visual Inspection notebook and copy it into your Forge project.',['Confirm <strong>Your Forge entity/project</strong>.','Click <strong>Connect and restore my inspection work</strong>.','Edit the attribute in <code>instrument_inspection_tool</code>, then click <strong>Send my first inspection trace</strong>.'],'Find your attribute and the returned NumPy version in Agent Lens.','Hosted authentication comes from the copied notebook. A laptop uses uv run wandb login. The core path has no inference calls; notebook compute remains separately billed.','0:10')
add('trace-code','The trace describes a call that actually ran',code('with tracing.Tool(\n    name=observation["name"],\n    arguments=observation["arguments"],\n    result=observation["result"],\n    started_at=stamp(observation["started_at"]),\n    ended_at=stamp(observation["ended_at"]),\n) as tool:\n    tool.set_attributes({"workshop.exercise": "pcb-inspection"})','1-4|5-6|7-8|all')+note('Open the same call in Agent Lens. Match its arguments, result and timing to these fields.'), 'The training receipt is recorded before export. A publication failure does not mean the classifier failed. Retrying publication must not train it again.', '0:14')
exercise('inspect','Inspect one board before revealing its label','Notebook step: Inspect the boards.',['Click <strong>Download and verify the PCB1 teaching data</strong>.','Choose a training board. Explain what would make you inspect it.','Turn on <strong>Reveal the published defect label and mask</strong>.'],'Describe the annotated region without treating the mask as an input to your detector.','This is a participant decision, not a model evaluation. Give people a minute to make their own assessment before discussion.','0:18')
add('encoder','Reuse a fixed image encoder','<div class="flow"><div class="box">224 × 224<br>RGB photo</div><span>→</span><div class="box">Fixed<br>ResNet-18</div><span>→</span><div class="box">512-value<br>whole image</div></div><div v-click class="box">Also keep a 14 × 14 grid of local features. A small defect occupies only part of the board.</div>', 'The ImageNet encoder is fixed. Fitting our logistic classifier changes its weights but not ResNet-18. The small cache can be reused in a CPU notebook.', '0:24')
add('patches','Compare each patch with real normal examples','<div class="two-col"><div class="box"><h2>First recipe</h2><p>Compare a patch with the average normal patch at that location.</p><p class="small">An average can fall between different normal appearances.</p></div><div v-click class="box"><h2>Follow-up recipe</h2><p>Find the closest actual normal training patch at that location.</p><p class="small">Training cases cannot match themselves.</p></div></div>'+note('The same reference bank is used for validation and test. Those boards never enter the bank.'), 'This is the concrete mechanism we changed after the first recipe failed its AP gate. It is not a universal claim about nearest neighbors.', '0:30')
exercise('features','Add local information to the classifier','Notebook step: Compute image features.',['Complete <code>build_features</code>: calculate patch errors, apply <code>np.log1p</code>, and flatten one row per board.','Append the patch values to the whole-image vector along axis 1.','Click <strong>Check my patch-feature function</strong>.'],'The check preserves board order and verifies both whole-image and nearest-patch behavior.','The learner function is passed into fitting and saved with the freeze. Final evaluation reloads that saved source, not the current draft.','0:35','answer-features')
add('cache','Check the feature cache without rebuilding everything',code('weights = teaching.fetch_weights(weights_path)\nresult = teaching.recompute_batch(data_root, weights)\nassert result["matching_cached_features"]')+note('Optional button: Recompute four cached board features. Downloads pinned weights; no model-provider call.'), 'The retained lossless inputs allow exact feature comparison. The prepared full cache took 39.25 seconds on the preparation Mac using two Torch CPU threads. This is not an attendee timing guarantee.', '0:48')
add('classifier','Fit a first detector on whole-image features',code('model = inspection.fit_classifier(\n    data, fit_rows, method,\n    build_features=build_features,\n    C=0.03,\n)\nvalidation_scores = inspection.score(data, validation_rows, model)','1-4|6|all')+note('C controls regularization. This worked recipe fixes C before your run; labels and training cases are the same.'), 'Do not describe this as training a vision foundation model. We fit a logistic classifier over fixed encoder outputs. Patch distances add features but do not use pixel masks.', '0:55')
add('threshold','A detector score still needs an operating rule','<div class="cards"><div class="card"><strong>Lower threshold</strong><p>Flag more boards. Usually catch more defects and create more false alarms.</p></div><div class="card"><strong>Higher threshold</strong><p>Flag fewer boards. Some defects can pass unnoticed.</p></div><div class="card"><strong>Review band</strong><p>Send uncertain cases to people. Report that extra workload separately.</p></div></div>', 'Scores are decision values, not calibrated defect probabilities. The optional review margin is in score units. A valid threshold function does not make the policy safe.', '1:00')
exercise('threshold-exercise','Implement the validation threshold','Notebook step: Train the whole-image baseline.',['In <code>choose_threshold</code>, sort the scores of known validation defects.','Choose the largest cutoff that still catches at least 90% of them.','Click <strong>Check my threshold function</strong>, then <strong>Train the whole-image baseline</strong>.'],'Open one validation miss or false alarm before adding patch features.','Allow participants to finish the local check before training. The 90 percent requirement constrains recall on validation only, not a guarantee for the final set.','1:05','answer-threshold')
add('metrics','Keep ranking quality and operating errors separate','<table class="clean-table"><tbody><tr><th>Measure</th><th>Question it answers</th></tr><tr><td>Average precision</td><td>Are defective boards ranked ahead of normal boards?</td></tr><tr><td>Misses and false alarms</td><td>What happens at the frozen threshold?</td></tr><tr><td>Review volume</td><td>How many decisions are handed to a person?</td></tr></tbody></table>', 'AP summarizes precision over recall levels. Do not compare it to accuracy or confuse a change in review volume with better detection.', '1:15')
add('forge','Follow one trained classifier through Forge','<div class="flow"><div class="box">Agent Lens<br><small>training operation</small></div><span>→</span><div class="box">W&B run<br><small>settings + metrics</small></div><span>→</span><div class="box">Artifact<br><small>classifier + source</small></div></div>'+note('Open your own links. Find C, the representation, the validation errors, and the saved classifier file.'), 'These are actual inspection tasks rather than a generic dashboard tour. If export is unavailable, state that the execution is saved and show the publication retry.', '1:22')
add('forge-training','Read the recorded training call', '<div class="native-pair"><div class="native-crop"><img src="/images/agent-lens-training-original.png" alt="Native Agent Lens tool input and validation output for the nearest-patch classifier"><span class="pin one">1</span><span class="pin two">2</span></div><div class="native-notes"><h2>1 · What ran</h2><p>397 fitting boards.<br>Nearest-patch features.<br>C = 0.03.</p><h2>2 · What it returned</h2><p>On <strong>132 validation boards</strong>: AP 0.883923, one missed defect, four false alarms.</p><p class="small">These are validation results. Final-test AP is reported later.</p></div></div>' + note('<a href="https://forge.coreweave.com/agent-lens/wandb/forge-workshop-kit/conversations/ff65c2eaa1cc5c5cf8adb6cb706f5f52">Open this recorded call in Agent Lens ↗</a> · Cropped for legibility; the source capture is included.'), 'Show the exact method, training count and C arguments. Then match the returned classifier path, saved file hash and validation metrics. The next execution uses the saved model. Native capture uses the rehearsal project; participants open their own links. This is tool-only tracing: there was no model-provider call.', '1:25 · RECORDED')

