add('native-board','Inspect the board behind a prediction','<div class="eval-native-states"><div>'+eval_capture(True,items=[('Look at the board','This is the actual PCB1 test photograph.'),('Compare predictions','All four flag this board as defective.'),('Check the threshold','Read each score against that detector’s frozen cutoff.')])+'</div><div v-click="1" class="eval-native-overlay">'+eval_capture('mask',items=[('Read the annotation','White pixels mark the dataset’s reference defects.'),('Compare decisions','All four detectors flag this same board.'),('Check the result','Every prediction matches the defective label on this case.')])+'</div></div>','Click once to reveal the reference defect mask for the same board. White pixels are supplied annotations, not model localization. Do not claim a patch heatmap is a causal explanation or segmentation model. Masks are used for inspection, not classifier inputs. Average precision ranks all boards; one row explains a particular operating decision. The separate CES v2 API remains unavailable; this is the working native Preview.','2:30')
add('failure','The first worked recipe did not pass its gate','<table class="clean-table"><tbody><tr><th>First frozen recipe</th><th>Average precision</th><th>Misses</th><th>False alarms</th></tr><tr><td>Whole image</td><td>0.861762</td><td>4</td><td>36</td></tr><tr><td>Mean-patch + whole image</td><td>0.855382</td><td>2</td><td>33</td></tr></tbody></table>'+note('Its declared primary measure was average precision. Fewer operating errors did not turn the AP loss into a pass.'), 'Preserve the failed result and all active/random review outcomes. This is why we choose the criterion before seeing results.', '2:31 · RECORDED')
add('retest','The bounded follow-up improved this teaching retest','<table class="clean-table"><tbody><tr><th>Frozen follow-up</th><th>Average precision</th><th>Misses / 40</th><th>False alarms / 402</th></tr><tr><td>Whole image</td><td>0.872900</td><td>4</td><td>23</td></tr><tr><td>Nearest-patch + whole image</td><td>0.885742</td><td>3</td><td>18</td></tr></tbody></table>'+note('One predeclared validation grid; already-inspected final images. AP gain: 1.284 points. This is a teaching retest, not fresh benchmark evidence.'), 'Both methods selected C=.03 from the same grid. No further tuning followed the retest. This result does not establish repeatability on a new product.', '2:33 · RECORDED')
